#ifndef LUGALOS_DRIVERS_FONT_SERIF_FACES_H
#define LUGALOS_DRIVERS_FONT_SERIF_FACES_H

#include <stdint.h>

/* The reader's extra serif sizes, generated by tools/gen_serif_faces.py from GentiumBook-Regular.ttf;
 * do not edit. Glyphs 0x20..0x7E: an advance each, and 4-bit coverage rows of
 * ceil(h / 2) bytes (the left pixel in the low nibble). Only where
 * UGUI_TEXT_SIZES is defined (drivers/ugui.h). */

#define FONT_SERIF_FACES_FIRST 0x20
#define FONT_SERIF_FACES_COUNT 95

extern const uint8_t font_serif13_widths[FONT_SERIF_FACES_COUNT];
extern const uint8_t font_serif13_aa[FONT_SERIF_FACES_COUNT][13][7];
extern const uint8_t font_serif24_widths[FONT_SERIF_FACES_COUNT];
extern const uint8_t font_serif24_aa[FONT_SERIF_FACES_COUNT][24][12];
extern const uint8_t font_serif40_widths[FONT_SERIF_FACES_COUNT];
extern const uint8_t font_serif40_aa[FONT_SERIF_FACES_COUNT][40][20];

#endif /* LUGALOS_DRIVERS_FONT_SERIF_FACES_H */
